#!/usr/bin/env bash
# Build a directly-installable Android APK on your own machine.
#
# SOOMAALI: Kani wuxuu kuu dhisayaa APK aad taleefanka Android ku rakibi
# karto. Waxaad u baahan tahay: Node.js, JDK 17, iyo Android SDK
# (Android Studio). Mac/iPhone looma isticmaalo script-kan.
#
# Requirements: Node.js ≥ 22, JDK 17, Android SDK (via Android Studio),
# ANDROID_HOME set. Output: build-output/Babelish.apk
#
# The APK is signed with the debug keystore generated by `expo prebuild`
# — perfect for installing/testing/sharing, NOT for Google Play. For the
# Play Store use:  npm run build:aab   (EAS, signed .aab)
set -euo pipefail

cd "$(dirname "$0")/.."

if ! command -v java >/dev/null 2>&1; then
  echo "✘ Java is not installed. Install JDK 17 (e.g. Temurin) and try again." >&2
  exit 1
fi
if [ -z "${ANDROID_HOME:-}" ] && [ -z "${ANDROID_SDK_ROOT:-}" ]; then
  echo "✘ ANDROID_HOME is not set. Install Android Studio / the Android SDK first." >&2
  echo "  No local SDK? Use GitHub instead: Actions → 'Build mobile (APK + iOS)'." >&2
  exit 1
fi

echo "==> Installing dependencies"
npm install

echo "==> Release gate"
npm run check:release

echo "==> Generating native Android project (expo prebuild)"
npx expo prebuild --platform android --clean

echo "==> Building release APK (Gradle assembleRelease)"
(cd android && ./gradlew assembleRelease --no-daemon)

APK="$(find android/app/build/outputs/apk/release -name '*.apk' | head -n 1)"
if [ -z "$APK" ]; then
  echo "✘ No APK was produced — scroll up for the Gradle error." >&2
  exit 1
fi

mkdir -p build-output
cp "$APK" build-output/Babelish.apk
echo ""
echo "✓ APK ready: build-output/Babelish.apk"
echo "  Copy it to an Android phone and tap it to install"
echo "  (you may need: Settings → allow 'Install unknown apps')."
